.question-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

.question-number {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-accent);
  background: var(--color-accent-light);
  padding: 3px 9px;
  border-radius: 999px;
}

.multi-badge {
  font-size: 0.7rem;
  font-weight: 500;
  color: var(--color-text-help);
  letter-spacing: 0.01em;
}

.form-field legend {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--color-text-primary);
  margin-bottom: 6px;
  display: block;
  line-height: 1.4;
}

.help-text {
  font-size: 0.85rem;
  color: var(--color-text-help);
  margin-bottom: 18px;
  display: flex;
  align-items: flex-start;
  gap: 6px;
}

.help-text svg {
  flex-shrink: 0;
  margin-top: 2px;
  color: var(--color-text-help);
}

/* Options list */
.options-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 18px;
}

.option-item label {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, box-shadow 0.15s;
  font-size: 0.95rem;
  color: var(--color-text-primary);
  user-select: none;
}

.option-item label:hover {
  background: var(--color-accent-light);
  border-color: var(--color-accent);
}

/* Hide native checkbox */
.option-item input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
  pointer-events: none;
}

