.custom-check {
  width: 20px;
  height: 20px;
  min-width: 20px;
  border: 2px solid var(--color-border);
  border-radius: 5px;
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s, border-color 0.15s, box-shadow 0.15s;
  flex-shrink: 0;
}

.custom-check svg {
  display: none;
  width: 12px;
  height: 12px;
}

/* Checked state */
.option-item input[type="checkbox"]:checked + .custom-check {
  background: var(--color-accent);
  border-color: var(--color-accent);
}

.option-item input[type="checkbox"]:checked + .custom-check svg {
  display: block;
}

.option-item input[type="checkbox"]:checked ~ .option-text {
  color: var(--color-accent);
  font-weight: 500;
}

/* Focus-visible outline on the label */
.option-item input[type="checkbox"]:focus-visible + .custom-check {
  box-shadow: var(--shadow-focus);
  border-color: var(--color-accent);
}

/* Selected label highlight */
.option-item:has(input:checked) label {
  background: var(--color-accent-light);
  border-color: var(--color-accent);
}

/* Submit area */
.submit-area {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 14px;
  margin-top: 8px;
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 32px;
  background: var(--color-accent);
  color: #fff;
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  box-shadow: 0 2px 8px rgba(99,102,241,0.25);
}

.btn-submit:hover {
  background: var(--color-accent-hover);
  box-shadow: 0 4px 16px rgba(99,102,241,0.35);
}

.btn-submit:active {
  transform: scale(0.98);
}

.btn-submit:focus-visible {
  outline: none;
  box-shadow: var(--shadow-focus);
}

