.result-banner {
  display: none;
  padding: 16px 20px;
  border-radius: var(--radius-md);
  font-size: 0.95rem;
  font-weight: 500;
  align-items: center;
  gap: 10px;
}

.result-banner.show {
  display: flex;
}

.result-banner.success {
  background: #f0fdf4;
  color: #166534;
  border: 1px solid #bbf7d0;
}

.result-banner.partial {
  background: #fffbeb;
  color: #92400e;
  border: 1px solid #fde68a;
}

.result-banner svg {
  flex-shrink: 0;
}

