  padding: 28px 28px 24px;
  box-shadow: var(--shadow-card);
  transition: border-color 0.2s;
}

.form-field:focus-within {
  border-color: var(--color-border-focus);
}

.question-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

.question-number {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-accent);
  background: var(--color-accent-light);
  padding: 3px 9px;
  border-radius: 999px;
}

.multi-badge {
  font-size: 0.7rem;
  font-weight: 500;
  color: var(--color-text-help);
  letter-spacing: 0.01em;
}

.form-field legend {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--color-text-primary);
  margin-bottom: 6px;
  display: block;
  line-height: 1.4;
}

.help-text {
  font-size: 0.85rem;
