.option-item input[type="checkbox"]:focus-visible + .custom-check {
  box-shadow: var(--shadow-focus);
  border-color: var(--color-accent);
}

/* Selected label highlight */
.option-item:has(input:checked) label {
  background: var(--color-accent-light);
  border-color: var(--color-accent);
}

/* Submit area */
.submit-area {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 14px;
  margin-top: 8px;
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 32px;
  background: var(--color-accent);
  color: #fff;
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  box-shadow: 0 2px 8px rgba(99,102,241,0.25);
}

.btn-submit:hover {
  background: var(--color-accent-hover);
  box-shadow: 0 4px 16px rgba(99,102,241,0.35);
}

.btn-submit:active {
  transform: scale(0.98);
}

.btn-submit:focus-visible {
  outline: none;
  box-shadow: var(--shadow-focus);
}

/* Result banner */
.result-banner {
  display: none;
  padding: 16px 20px;
  border-radius: var(--radius-md);
  font-size: 0.95rem;
  font-weight: 500;
  align-items: center;
  gap: 10px;
}

.result-banner.show {
  display: flex;
}

.result-banner.success {
  background: #f0fdf4;
  color: #166534;
  border: 1px solid #bbf7d0;
}

.result-banner.partial {
  background: #fffbeb;
  color: #92400e;
  border: 1px solid #fde68a;
}

.result-banner svg {
  flex-shrink: 0;
}

/* Validation error state */
.form-field.has-error {
  border-color: var(--color-error);
}

.error-msg {
  display: none;
  font-size: 0.8rem;
  color: var(--color-error);
  margin-top: 10px;
  align-items: center;
  gap: 5px;
}

.form-field.has-error .error-msg {
  display: flex;
}

@media (max-width: 480px) {
  body {
    padding: 32px 12px 60px;
  }

  .form-field {
    padding: 22px 18px 18px;
  }

  .quiz-header h1 {
    font-size: 1.6rem;
  }
}
