+const CORRECT_ANSWERS = {
+  q1: ['b', 'c'],       // Python, JavaScript
+  q2: ['a', 'd'],       // Compiled: C++, Rust
+  q3: ['b', 'c', 'd'],  // HTML, SQL, CSS — not general-purpose programming languages
+};
+
+const SCORE_MESSAGES = {
+  3: "Perfect score! You really know your computer languages. 🎉",
+  2: "Great job — 2 out of 3 correct!",
+  1: "1 out of 3 correct. Keep learning!",
+  0: "No correct answers this time. Give it another shot!",
+};
+
+function getChecked(name) {
+  return [...document.querySelectorAll(`input[name="${name}"]:checked`)]
+    .map(el => el.value);
+}
+
+function arraysEqual(a, b) {
+  if (a.length !== b.length) return false;
+  const sa = [...a].sort();
+  const sb = [...b].sort();
+  return sa.every((v, i) => v === sb[i]);
+}
+
+function clearErrors() {
+  document.querySelectorAll('.form-field').forEach(f => f.classList.remove('has-error'));
+}
+
+function validate() {
+  let valid = true;
+  ['q1', 'q2', 'q3'].forEach(name => {
+    if (getChecked(name).length === 0) {
+      document.getElementById(`field-${name}`).classList.add('has-error');
+      valid = false;
+    }
+  });
+  return valid;
+}
+
+document.getElementById('quiz-form').addEventListener('submit', function (e) {
+  e.preventDefault();
+  clearErrors();
+
+  if (!validate()) {
+    // Focus first invalid field
+    const firstError = document.querySelector('.form-field.has-error');
+    firstError?.querySelector('input')?.focus();
+    return;
+  }
+
+  let score = 0;
+  ['q1', 'q2', 'q3'].forEach(name => {
+    if (arraysEqual(getChecked(name), CORRECT_ANSWERS[name])) score++;
+  });
+
+  const banner = document.getElementById('result-banner');
+  const bannerText = document.getElementById('result-text');
+  bannerText.textContent = SCORE_MESSAGES[score];
+  banner.className = 'result-banner show ' + (score === 3 ? 'success' : 'partial');
+  banner.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
+});
+
+// Clear error on any selection within a field
+document.querySelectorAll('input[type="checkbox"]').forEach(cb => {
+  cb.addEventListener('change', () => {
+    cb.closest('.form-field')?.classList.remove('has-error');
+  });
+});
+
')
